import json, glob
import jsonschema
schema=json.load(open("schemas/relevance-batch.schema.json"))
allok=True
for f in sorted(glob.glob("workspace/runs/2026-08-08-200543/tasks/relevance_batch/*.output.json")):
    tid=f.split('/')[-1].replace('.output.json','')
    try:
        d=json.load(open(f))
    except Exception as e:
        print(f"{tid}: INVALID JSON: {e}"); allok=False; continue
    errs=[]
    inp=json.load(open(f.replace('.output.json','.input.json')))
    in_ids=[c['candidate_id'] for c in inp['candidates']]
    out_ids=[r.get('candidate_id') for r in d.get('results',[])]
    if sorted(in_ids)!=sorted(out_ids): errs.append("id mismatch")
    if len(out_ids)!=len(set(out_ids)): errs.append("dup ids")
    if d.get('_task')!=inp.get('_task'): errs.append("_task differs")
    for r in d.get('results',[]):
        if not (0<=r.get('score',-1)<=100): errs.append(f"{r.get('candidate_id')}: bad score")
        tv=r.get('technology_value')
        if tv is None: errs.append(f"{r.get('candidate_id')}: no tech_value")
        else:
            for dim in ["novelty","architecture_impact","industry_signal","project_alignment"]:
                if dim not in tv or not (0<=tv[dim].get('score',-1)<=5): errs.append(f"{r.get('candidate_id')}: bad tv {dim}")
    try:
        jsonschema.validate({"results":d.get('results',[])}, schema)
    except jsonschema.ValidationError as e:
        errs.append(f"schema: {e.message[:60]}")
    ft=sum(1 for r in d.get('results',[]) if r.get('fulltext_required'))
    if errs: print(f"{tid}: ISSUES: {' | '.join(errs[:4])}"); allok=False
    else: print(f"{tid}: OK  ft={ft}")
print("\nALL CLEAN" if allok else "\nSOME ISSUES REMAIN")
