import json, glob
import jsonschema
schema=json.load(open("schemas/facts.schema.json"))
allok=True
for f in sorted(glob.glob("workspace/runs/2026-08-08-200543/tasks/fact_extraction/*.output.json")):
    tid=f.split('/')[-1].replace('.output.json','')
    inp=json.load(open(f.replace('.output.json','.input.json')))
    try:
        d=json.load(open(f))
    except Exception as e:
        print(f"{tid}: INVALID JSON: {e}"); allok=False; continue
    errs=[]
    # _task
    if d.get('_task')!=inp.get('_task'): errs.append("_task differs")
    # title match
    if d.get('title')!=inp['source']['title']: errs.append(f"title mismatch: out={d.get('title','')[:40]!r} in={inp['source']['title'][:40]!r}")
    # fetch_status -> primary_source_resolved
    fs=inp['document'].get('fetch_status')
    psr=d.get('primary_source_resolved')
    if fs=='FETCHED' and psr is not True: errs.append(f"fetch_status=FETCHED but primary_source_resolved={psr}")
    # quality_score range
    qs=d.get('quality_score')
    if not (isinstance(qs,(int,float)) and 0<=qs<=100): errs.append(f"bad quality_score={qs}")
    # evidence locators
    for e in d.get('evidence',[]):
        if not e.get('source_locator'): errs.append("evidence missing source_locator")
    # schema (strip _task)
    body={k:v for k,v in d.items() if k!='_task'}
    try:
        jsonschema.validate(body, schema)
    except jsonschema.ValidationError as e:
        errs.append(f"schema: {e.message[:70]} @ {list(e.absolute_path)}")
    n_ev=len(d.get('evidence',[]))
    n_gaps=len(d.get('evidence_gaps',[]))
    if errs: print(f"{tid}: ISSUES: {' | '.join(errs[:3])}"); allok=False
    else: print(f"{tid}: OK  qs={qs} ev={n_ev} gaps={n_gaps} psr={psr} | {inp['source']['title'][:45]}")
print("\nALL CLEAN" if allok else "\nSOME ISSUES")
