def save(f,d): json.dump(d,open(f,"w"),ensure_ascii=False,indent=2)

for f in sorted(glob.glob(f"{base}/*.output.json")):
    tid=f.split('/')[-1].replace('.output.json','')
    d=load(f); changed=False
    # fix numeric baseline/condition -> string
    for e in d.get("evidence",[]):
        for k in ("baseline","condition"):
            v=e.get(k)
            if isinstance(v,bool):
                e[k]=str(v); changed=True
            elif isinstance(v,(int,float)):
                e[k]=str(v); changed=True
    # fix value bool -> string (value allows string|number|null, not bool)
    for e in d.get("evidence",[]):
        if isinstance(e.get("value"),bool): e["value"]=str(e["value"]); changed=True
    # trim terms >8 and bad-length terms
