import json, glob, jsonschema
base="workspace/runs/2026-08-08-200543/tasks/item_writing_batch"
schema=json.load(open("schemas/item-writing-batch.schema.json"))
allok=True
for f in sorted(glob.glob(f"{base}/*.output.json")):
    tid=f.split('/')[-1].replace('.output.json','')
    inp=json.load(open(f.replace('.output.json','.input.json')))
    try: d=json.load(open(f))
    except Exception as e: print(f"{tid}: INVALID JSON {e}"); allok=False; continue
    errs=[]
    if d.get('_task')!=inp.get('_task'): errs.append("_task differs")
    in_ids=[it["event_id"] for it in inp["items"]]
    out_ids=[r.get("event_id") for r in d.get("results",[])]
    if sorted(in_ids)!=sorted(out_ids): errs.append(f"id mismatch in={in_ids} out={out_ids}")
    # schema
    try: jsonschema.validate({"results":d.get("results",[])}, schema)
    except jsonschema.ValidationError as e: errs.append(f"schema: {e.message[:70]} @ {list(e.absolute_path)}")
    # metadata preservation
    in_by={it["event_id"]:it for it in inp["items"]}
    for r in d.get("results",[]):
        it=in_by.get(r["event_id"]); item=r.get("item",{})
        if not it: continue
        if item.get("topic_name")!=it["topic"].get("name"): errs.append(f"{r['event_id'][:8]} topic_name")
        if item.get("direction_name")!=it["direction"].get("name"): errs.append(f"{r['event_id'][:8]} direction_name")
        if item.get("score")!=it["score"]: errs.append(f"{r['event_id'][:8]} score {item.get('score')} vs {it['score']}")
        # published_at matches one of input sources
        in_pa=[s.get("published_at") for s in it["sources"]]
        if item.get("published_at") not in in_pa: errs.append(f"{r['event_id'][:8]} published_at {item.get('published_at')}")
        # source urls preserved
        in_urls=[s.get("url") for s in it["sources"]]
        out_urls=[s.get("url") for s in item.get("sources",[])]
        for u in in_urls:
            if u not in out_urls: errs.append(f"{r['event_id'][:8]} missing url {u}")
        # trailing punctuation check on substantive fields
        for fld in ("core_conclusion","mechanism","result","boundary","project_relevance"):
            v=item.get(fld,"")
            if v and v[-1] in "。，：；、…,;:.": errs.append(f"{r['event_id'][:8]} {fld} ends with punct")
    print(f"{tid}: {'OK' if not errs else 'ISSUES:'+' | '.join(errs[:4])}")
    if errs: allok=False
print("\nALL CLEAN" if allok else "\nISSUES REMAIN")
